// Coucou plugin for OpenCode — generated by Coucou.
// Forwards OpenCode's events to Coucou's relay (coucou-hook), fire-and-forget:
// OpenCode never waits on it, and nothing happens when Coucou is closed.
import { spawn } from 'node:child_process';

const HOOK = "C:\\Users\\harsh\\AppData\\Local\\Coucou\\bin\\coucou-hook.exe";
const EVENT_MAP = {
  'session.created': 'SessionStart',
  'session.idle': 'Stop',
  'session.error': 'StopFailure',
  'session.deleted': 'SessionEnd',
};

function forward(hook_event_name, payload) {
  try {
    const p = spawn(HOOK, ['--agent', 'opencode'], {
      stdio: ['pipe', 'ignore', 'ignore'],
      detached: process.platform !== 'win32',
      windowsHide: true,
    });
    p.on('error', () => {});
    p.stdin.on('error', () => {});
    p.stdin.end(JSON.stringify({ hook_event_name, ...payload }) + '\n');
    p.unref();
  } catch {}
}

export const CoucouPlugin = async ({ directory } = {}) => ({
  event: async ({ event }) => {
    const hook_event_name = EVENT_MAP[event?.type];
    if (!hook_event_name) return;
    const props = event?.properties || {};
    forward(hook_event_name, {
      session_id: props.sessionID || props.info?.id || '',
      cwd: directory || '',
    });
  },
  'tool.execute.before': async (input, output) => {
    forward('PreToolUse', {
      session_id: input?.sessionID || '',
      cwd: directory || '',
      tool_name: typeof input?.tool === 'string' ? input.tool : '',
      tool_input: output?.args ?? null,
    });
  },
  'tool.execute.after': async (input) => {
    forward('PostToolUse', {
      session_id: input?.sessionID || '',
      cwd: directory || '',
      tool_name: typeof input?.tool === 'string' ? input.tool : '',
    });
  },
});

export default {
  id: 'coucou',
  setup: async (ctx = {}) => {
    const dir = ctx.directory || '';
    if (ctx.tool?.hook) {
      try {
        ctx.tool.hook('execute.before', async (input, output) => {
          forward('PreToolUse', {
            session_id: input?.sessionID || '',
            cwd: dir,
            tool_name: typeof input?.tool === 'string' ? input.tool : '',
            tool_input: output?.args ?? input?.input ?? null,
          });
        });
        ctx.tool.hook('execute.after', async (input) => {
          forward('PostToolUse', {
            session_id: input?.sessionID || '',
            cwd: dir,
            tool_name: typeof input?.tool === 'string' ? input.tool : '',
          });
        });
      } catch {}
    }
    if (ctx.event?.subscribe) {
      (async () => {
        try {
          for await (const event of ctx.event.subscribe()) {
            const hook_event_name = EVENT_MAP[event?.type];
            if (!hook_event_name) continue;
            const props = event?.properties || {};
            forward(hook_event_name, {
              session_id: props.sessionID || props.info?.id || event?.sessionID || '',
              cwd: dir,
            });
          }
        } catch {}
      })();
    }
    return CoucouPlugin(ctx);
  },
  server: CoucouPlugin,
};
